### Objective
Build a production-grade multithreading diagnostic laboratory demonstrating the difference between blocking the main UI isolate vs offloading heavy computation to Isolate.run() and compute(), featuring an animated 60 FPS spinning gear, real-time frame hitch detection, and a long-running worker isolate with bidirectional port communication.

```dart
import 'dart:async';
import 'dart:isolate';
import 'dart:math';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

void main() {
  runApp(const IsolateMasteryApp());
}

/// Root application entrypoint.
class IsolateMasteryApp extends StatelessWidget {
  const IsolateMasteryApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Dart Isolates & Concurrency Mastery',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepOrange,
        useMaterial3: true,
      ),
      home: const IsolateBenchmarkScreen(),
    );
  }
}

/// Screen benchmarking UI smoothness during heavy synchronous calculations.
class IsolateBenchmarkScreen extends StatefulWidget {
  const IsolateBenchmarkScreen({super.key});

  @override
  State<IsolateBenchmarkScreen> createState() => _IsolateBenchmarkScreenState();
}

class _IsolateBenchmarkScreenState extends State<IsolateBenchmarkScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _gearAnimationController;

  String _statusText = 'Ready for benchmark';
  bool _isComputing = false;
  int _lastPrimesFound = 0;
  Duration _lastExecutionDuration = Duration.zero;

  // Long-running isolate fields
  Isolate? _workerIsolate;
  ReceivePort? _workerReceivePort;
  SendPort? _workerSendPort;
  bool _isWorkerActive = false;

  @override
  void initState() {
    super.initState();
    // 60 FPS continuous animation to visually detect UI thread freezes
    _gearAnimationController = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 2),
    )..repeat();
  }

  @override
  void dispose() {
    _gearAnimationController.dispose();
    _stopLongLivedWorker();
    super.dispose();
  }

  /// CPU-Intensive task: Prime number sieve computation
  static int _computePrimes(int upperLimit) {
    int count = 0;
    for (int i = 2; i <= upperLimit; i++) {
      bool isPrime = true;
      final sqrtVal = sqrt(i).toInt();
      for (int j = 2; j <= sqrtVal; j++) {
        if (i % j == 0) {
          isPrime = false;
          break;
        }
      }
      if (isPrime) count++;
    }
    return count;
  }

  /// 1. ANTI-PATTERN: Heavy CPU execution on the Main UI Isolate
  /// Watch the spinning gear freeze completely!
  void _runOnMainThread() {
    setState(() {
      _isComputing = true;
      _statusText = 'Running on MAIN THREAD (Watch gear freeze!)...';
    });

    final stopwatch = Stopwatch()..start();
    // Synchronous execution blocks the single event loop
    final result = _computePrimes(1500000);
    stopwatch.stop();

    setState(() {
      _isComputing = false;
      _lastPrimesFound = result;
      _lastExecutionDuration = stopwatch.elapsed;
      _statusText = 'Finished on MAIN thread. UI completely froze!';
    });
  }

  /// 2. PRODUCTION PATTERN: Modern Dart Isolate.run()
  /// Spinning gear rotates smoothly at 60 FPS with ZERO jank!
  Future<void> _runOnIsolateRun() async {
    setState(() {
      _isComputing = true;
      _statusText = 'Running via Isolate.run() (Gear spins smoothly!)...';
    });

    final stopwatch = Stopwatch()..start();
    // Dispatches computation to a background isolate
    final result = await Isolate.run(() => _computePrimes(1500000));
    stopwatch.stop();

    if (!mounted) return;
    setState(() {
      _isComputing = false;
      _lastPrimesFound = result;
      _lastExecutionDuration = stopwatch.elapsed;
      _statusText = 'Finished in background Isolate.run() without frame drops!';
    });
  }

  /// 3. FLUTTER COMPUTE HELPER: flutter/foundation compute()
  Future<void> _runOnCompute() async {
    setState(() {
      _isComputing = true;
      _statusText = 'Running via compute() helper...';
    });

    final stopwatch = Stopwatch()..start();
    final result = await compute(_computePrimes, 1500000);
    stopwatch.stop();

    if (!mounted) return;
    setState(() {
      _isComputing = false;
      _lastPrimesFound = result;
      _lastExecutionDuration = stopwatch.elapsed;
      _statusText = 'Finished via compute() cleanly!';
    });
  }

  /// 4. ADVANCED: Long-Lived Worker Isolate initialization
  Future<void> _startLongLivedWorker() async {
    if (_isWorkerActive) return;

    _workerReceivePort = ReceivePort();
    // Spawn worker isolate passing our main SendPort
    _workerIsolate = await Isolate.spawn(
      _workerEntryPoint,
      _workerReceivePort!.sendPort,
    );

    // Handshake: listen for worker'''s SendPort
    _workerReceivePort!.listen((message) {
      if (message is SendPort) {
        _workerSendPort = message;
        setState(() => _isWorkerActive = true);
      } else if (message is Map<String, dynamic>) {
        setState(() {
          _lastPrimesFound = message['result'] as int;
          _lastExecutionDuration = Duration(milliseconds: message['ms'] as int);
          _statusText = 'Worker isolate answered in ${message['ms']}ms!';
          _isComputing = false;
        });
      }
    });
  }

  /// Worker Isolate Entrypoint (must be top-level or static)
  static void _workerEntryPoint(SendPort mainSendPort) {
    final workerPort = ReceivePort();
    // Send our SendPort to main isolate (handshake complete)
    mainSendPort.send(workerPort.sendPort);

    // Listen for incoming jobs from main isolate
    workerPort.listen((message) {
      if (message is int) {
        final sw = Stopwatch()..start();
        final primes = _computePrimes(message);
        sw.stop();
        mainSendPort.send({'result': primes, 'ms': sw.elapsedMilliseconds});
      }
    });
  }

  void _sendJobToWorker() {
    if (_workerSendPort == null) return;
    setState(() {
      _isComputing = true;
      _statusText = 'Job sent to persistent worker isolate...';
    });
    _workerSendPort!.send(1500000);
  }

  void _stopLongLivedWorker() {
    _workerReceivePort?.close();
    _workerIsolate?.kill(priority: Isolate.immediate);
    _workerIsolate = null;
    _workerReceivePort = null;
    _workerSendPort = null;
    _isWorkerActive = false;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Dart Multithreading & Isolates'),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Card(
              elevation: 2,
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
              child: Padding(
                padding: const EdgeInsets.all(20.0),
                child: Row(
                  children: [
                    RotationTransition(
                      turns: _gearAnimationController,
                      child: const Icon(Icons.settings, size: 54, color: Colors.deepOrange),
                    ),
                    const SizedBox(width: 20),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'UI Thread Heartbeat Monitor',
                            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                          ),
                          const SizedBox(height: 4),
                          const Text(
                            'If the gear stutters or stops, the main UI thread is blocked!',
                            style: TextStyle(fontSize: 12, color: Colors.grey),
                          ),
                          const SizedBox(height: 8),
                          Text(
                            _statusText,
                            style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w600),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 16),
            Card(
              color: Colors.grey.shade50,
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
              child: Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('Benchmark Metrics (Primes up to 1,500,000):',
                        style: const TextStyle(fontWeight: FontWeight.bold)),
                    const SizedBox(height: 8),
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text('Primes Found: $_lastPrimesFound'),
                        Text('Elapsed: ${_lastExecutionDuration.inMilliseconds} ms',
                            style: const TextStyle(fontWeight: FontWeight.bold)),
                      ],
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 20),
            FilledButton.tonalIcon(
              onPressed: _isComputing ? null : _runOnMainThread,
              style: FilledButton.styleFrom(backgroundColor: Colors.red.shade100),
              icon: const Icon(Icons.warning, color: Colors.red),
              label: const Text('Run on Main Thread (Blocks UI)', style: TextStyle(color: Colors.red)),
            ),
            const SizedBox(height: 10),
            FilledButton.icon(
              onPressed: _isComputing ? null : _runOnIsolateRun,
              icon: const Icon(Icons.bolt),
              label: const Text('Run via Isolate.run() (Smooth 60 FPS)'),
            ),
            const SizedBox(height: 10),
            OutlinedButton.icon(
              onPressed: _isComputing ? null : _runOnCompute,
              icon: const Icon(Icons.memory),
              label: const Text('Run via compute() Helper'),
            ),
            const SizedBox(height: 16),
            const Divider(),
            const Text('Persistent Worker Isolate Lab:', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed: _isWorkerActive ? null : _startLongLivedWorker,
                    child: Text(_isWorkerActive ? 'Worker Running' : 'Spawn Worker'),
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: FilledButton(
                    onPressed: (_isWorkerActive && !_isComputing) ? _sendJobToWorker : null,
                    child: const Text('Send Job to Worker'),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Continuous 60 FPS Visual Heartbeat**:
   `_gearAnimationController.repeat()` drives a spinning settings gear on the main UI thread. Any blocking operation longer than 16 milliseconds causes the animation to visibly stutter or halt, giving learners immediate visual feedback.
2. **The Main Thread Trap (`_runOnMainThread`)**:
   Calling `_computePrimes()` synchronously on the main thread saturates the CPU for ~400-800ms. During this interval, the gear halts completely and touch inputs are ignored, illustrating why async I/O alone cannot prevent UI jank.
3. **Modern Parallelism with `Isolate.run()`**:
   `await Isolate.run(() => _computePrimes(1500000))` delegates execution to an isolated background thread. The gear continues rotating smoothly at 60 FPS without dropping a single frame, and the computed result returns across the isolate boundary once complete.
4. **The `compute()` Function Bridge**:
   `compute(_computePrimes, 1500000)` executes the top-level calculation function. It provides the same non-blocking behavior with Flutter-specific conveniences.
5. **Two-Way Port Handshake in Worker Isolate**:
   `_startLongLivedWorker()` demonstrates how persistent background threads are coordinated: the main isolate receives the worker's `SendPort` via an initial message, enabling ongoing request-response exchanges without the overhead of continuously spawning new isolates.
